"""Virtual address space auditing for the wvas diagnostic collector.

The collector asks three questions about a target process:

``regions(pid)``
    Which parts of the virtual address space does the process have in use?

``file_backed_regions(pid)``
    Which of those parts are backed by a file on disk, and which file?

``modules(pid)``
    Which executable images are loaded, and where?

The answers are what the field engineers read when a machine reports
"something keeps the log file mapped" or "the process has no address space
left", so they have to describe the target process, not a snapshot of an
earlier call.

Two properties matter more than anything else here:

* addresses and sizes are reported at the full width the system reports them
  at, so a report can be laid next to a debugger without any rounding, and
* a file name is only reported when it can be handed to somebody who will try
  to open it, which means a drive letter or a UNC path, never a
  ``\\Device\\HarddiskVolumeN`` form.
"""

import ctypes

from . import _winapi as w
from .errors import WVasError

#: Initial size of the buffers used for path queries, in characters. Grown on
#: demand, because device paths easily exceed ``MAX_PATH``.
PATH_BUFFER_CHARS = 1024

#: Hard ceiling for a grown path buffer, in characters.
_MAX_PATH_BUFFER_CHARS = 32768

_PROTECTION_NAMES = {
    w.PAGE_NOACCESS: "none",
    w.PAGE_READONLY: "r",
    w.PAGE_READWRITE: "rw",
    w.PAGE_WRITECOPY: "wc",
    w.PAGE_EXECUTE: "x",
    w.PAGE_EXECUTE_READ: "xr",
    w.PAGE_EXECUTE_READWRITE: "xrw",
    w.PAGE_EXECUTE_WRITECOPY: "xwc",
}

_TYPE_NAMES = {
    w.MEM_IMAGE: "image",
    w.MEM_MAPPED: "mapped",
    w.MEM_PRIVATE: "private",
}

#: Devices whose paths denote a remote share rather than a local volume.
_UNC_DEVICES = (
    "\\device\\mup\\",
    "\\device\\lanmanredirector\\",
    "\\device\\webdavredirector\\",
)


def protection_name(protect):
    """Map a PAGE_* protection value onto its short textual name.

    Pure: only the constant is inspected, no process is queried. Modifier bits
    such as ``PAGE_GUARD`` or ``PAGE_NOCACHE`` are ignored.
    """
    try:
        protect = int(protect)
    except (TypeError, ValueError):
        return "?"
    return _PROTECTION_NAMES.get(protect & 0xFF, "?")


def type_name(region_type):
    """Map a MEM_* region type onto its short textual name.

    Pure: only the constant is inspected, no process is queried.
    """
    try:
        region_type = int(region_type)
    except (TypeError, ValueError):
        return "private"
    return _TYPE_NAMES.get(region_type, "private")


# ---------------------------------------------------------------------------
# process handles
# ---------------------------------------------------------------------------

def _check_platform(pid=None):
    if not w.IS_WINDOWS:
        raise WVasError(
            "virtual address space auditing requires Windows",
            kind="unsupported",
            pid=pid,
        )


def _validate_pid(pid):
    if isinstance(pid, bool) or not isinstance(pid, int) or pid <= 0:
        raise WVasError("pid must be a positive integer", kind="badarg", pid=pid)
    if pid > 0xFFFFFFFF:
        raise WVasError("pid is out of range", kind="badarg", pid=pid)
    return pid


def _open_process(pid):
    """Open ``pid`` for reading, or raise a classified :class:`WVasError`."""
    _validate_pid(pid)
    _check_platform(pid)

    ctypes.set_last_error(0)
    handle = w.OpenProcess(
        w.PROCESS_QUERY_INFORMATION | w.PROCESS_VM_READ, False, pid
    )
    if handle:
        return handle

    error = w.last_error()
    if error == w.ERROR_INVALID_PARAMETER:
        # Windows reports a pid that does not name a live process this way.
        raise WVasError(
            "no such process", kind="no-such-process", pid=pid
        )
    if error == w.ERROR_ACCESS_DENIED:
        raise WVasError(
            "process cannot be opened for reading",
            kind="access-denied",
            pid=pid,
        )
    raise WVasError(
        "OpenProcess failed with error %d" % (error,),
        kind="query-failed",
        pid=pid,
    )


# ---------------------------------------------------------------------------
# turning kernel object paths into paths a caller can open
# ---------------------------------------------------------------------------

def _logical_drives():
    """Return the drive roots (``'C:\\'``, ...) that currently exist."""
    size = w.GetLogicalDriveStringsW(0, None)
    if not size:
        return []
    buffer = ctypes.create_unicode_buffer(size + 1)
    written = w.GetLogicalDriveStringsW(size + 1, buffer)
    if not written:
        return []
    raw = buffer[:written]
    return [entry for entry in raw.split("\0") if entry]


def _query_dos_device(drive):
    """Return the NT device names ``drive`` (``'C:'``) resolves to."""
    chars = PATH_BUFFER_CHARS
    while chars <= _MAX_PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(chars)
        ctypes.set_last_error(0)
        written = w.QueryDosDeviceW(drive, buffer, chars)
        if written:
            return [entry for entry in buffer[:written].split("\0") if entry]
        if w.last_error() != w.ERROR_INSUFFICIENT_BUFFER:
            return []
        chars *= 2
    return []


def _device_map():
    """Map lower cased NT device names onto their DOS drive letters."""
    mapping = {}
    for root in _logical_drives():
        drive = root.rstrip("\\")
        if not drive.endswith(":"):
            continue
        for device in _query_dos_device(drive):
            mapping.setdefault(device.lower(), drive)
    return mapping


def _is_openable(path):
    """Is ``path`` something a caller can hand to ``open()`` as is?"""
    if not path:
        return False
    if path.startswith("\\\\?\\") or path.startswith("\\??\\"):
        return False
    if path.startswith("\\\\"):
        # UNC: \\server\share\... - needs at least a server component.
        rest = path[2:]
        return bool(rest) and not rest.startswith("\\") and not rest.startswith(".\\")
    if len(path) >= 3 and path[1] == ":" and path[2] == "\\" and path[0].isalpha():
        return True
    return False


def _strip_nt_prefix(path):
    """Drop a ``\\??\\`` / ``\\\\?\\`` prefix, expanding ``UNC\\`` as needed."""
    for prefix in ("\\??\\", "\\\\?\\"):
        if path.startswith(prefix):
            rest = path[len(prefix):]
            if rest[:4].upper() == "UNC\\":
                return "\\\\" + rest[4:]
            return rest
    return path


def _dos_path(path, device_map):
    """Translate a kernel object path into an openable DOS or UNC path.

    Returns ``None`` when the name cannot be expressed as a path the caller
    could open - a report must never carry a ``\\Device\\...`` string.
    """
    if not path:
        return None

    candidate = _strip_nt_prefix(path)
    if _is_openable(candidate):
        return candidate

    lowered = candidate.lower()

    # Remote shares: \Device\Mup\server\share\... -> \\server\share\...
    for device in _UNC_DEVICES:
        if lowered.startswith(device):
            rest = candidate[len(device):]
            if device == "\\device\\lanmanredirector\\" or device == "\\device\\webdavredirector\\":
                # May carry a ";Z:0000000000000000\" session prefix.
                if rest.startswith(";"):
                    _, sep, tail = rest.partition("\\")
                    rest = tail if sep else ""
            if not rest:
                return None
            return "\\\\" + rest

    # Local volumes: \Device\HarddiskVolume5\dir\file -> C:\dir\file
    best = None
    for device, drive in device_map.items():
        if lowered == device:
            return drive + "\\"
        prefix = device if device.endswith("\\") else device + "\\"
        if lowered.startswith(prefix):
            if best is None or len(device) > len(best[0]):
                best = (device, drive)
    if best is not None:
        device, drive = best
        return drive + "\\" + candidate[len(device):].lstrip("\\")

    return None


def _mapped_file_name(handle, address):
    """Return the raw kernel path of the file mapped at ``address``, or None."""
    chars = PATH_BUFFER_CHARS
    while chars <= _MAX_PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(chars)
        ctypes.set_last_error(0)
        written = w.GetMappedFileNameW(
            handle, ctypes.c_void_p(address), buffer, chars
        )
        if not written:
            # No file behind this address: an anonymous mapping, private or
            # reserved memory. That is not an error, it simply has no path.
            return None
        if written >= chars - 1:
            chars *= 2
            continue
        return buffer.value or None
    return None


def _module_paths(handle, device_map):
    """Map module base addresses onto their openable image paths.

    Returns an empty mapping when the module list cannot be read (for example
    across a bitness boundary); the region walk then falls back to the mapped
    file name of each image region.
    """
    if w.EnumProcessModulesEx is None:  # pragma: no cover - non Windows
        return {}

    count = 256
    while count <= 65536:
        array = (w.HMODULE * count)()
        needed = w.DWORD(0)
        ctypes.set_last_error(0)
        ok = w.EnumProcessModulesEx(
            handle,
            array,
            ctypes.sizeof(array),
            ctypes.byref(needed),
            w.LIST_MODULES_ALL,
        )
        if not ok:
            return {}
        returned = needed.value // ctypes.sizeof(w.HMODULE)
        if returned > count:
            count = returned + 64
            continue
        result = {}
        for index in range(returned):
            base = array[index]
            if not base:
                continue
            base = int(base)
            path = _module_file_name(handle, array[index], device_map)
            result[base] = path
        return result
    return {}


def _module_file_name(handle, module, device_map):
    """Return the openable path of ``module``, or ``None``."""
    chars = PATH_BUFFER_CHARS
    while chars <= _MAX_PATH_BUFFER_CHARS:
        buffer = ctypes.create_unicode_buffer(chars)
        ctypes.set_last_error(0)
        written = w.GetModuleFileNameExW(handle, module, buffer, chars)
        if not written:
            return None
        if written >= chars - 1:
            chars *= 2
            continue
        candidate = _strip_nt_prefix(buffer.value)
        if _is_openable(candidate):
            return candidate
        return _dos_path(buffer.value, device_map)
    return None


def _module_size(handle, module):
    """Return ``SizeOfImage`` for ``module``, or ``None`` when unavailable."""
    if w.GetModuleInformation is None:  # pragma: no cover - non Windows
        return None
    info = w.MODULEINFO()
    ctypes.set_last_error(0)
    if not w.GetModuleInformation(handle, module, ctypes.byref(info),
                                  ctypes.sizeof(info)):
        return None
    return int(info.SizeOfImage)


# ---------------------------------------------------------------------------
# the region walk
# ---------------------------------------------------------------------------

def _max_application_address():
    """Upper bound of the user mode address space on this machine."""
    if w.GetNativeSystemInfo is None:  # pragma: no cover - non Windows
        return 0x7FFFFFFF
    info = w.SYSTEM_INFO()
    w.GetNativeSystemInfo(ctypes.byref(info))
    return int(info.lpMaximumApplicationAddress or 0) or 0x7FFFFFFF


def _walk(handle, pid):
    """Yield the raw ``MEMORY_BASIC_INFORMATION`` snapshots of a process."""
    limit = _max_application_address()
    mbi = w.MEMORY_BASIC_INFORMATION()
    size = ctypes.sizeof(mbi)
    address = 0
    first = True
    while address <= limit:
        ctypes.set_last_error(0)
        written = w.VirtualQueryEx(
            handle, ctypes.c_void_p(address), ctypes.byref(mbi), size
        )
        if not written:
            error = w.last_error()
            if first and error not in (0, w.ERROR_INVALID_PARAMETER):
                raise WVasError(
                    "VirtualQueryEx failed with error %d" % (error,),
                    kind="query-failed",
                    pid=pid,
                )
            # Walking past the end of the address space ends the walk.
            return
        first = False

        base = int(mbi.BaseAddress or 0)
        region_size = int(mbi.RegionSize)
        yield base, region_size, int(mbi.State), int(mbi.Protect), \
            int(mbi.Type), int(mbi.AllocationBase or 0)

        next_address = base + region_size
        if region_size <= 0 or next_address <= address:
            return
        address = next_address


def regions(pid, include_reserved=True):
    """Return the regions of ``pid``'s virtual address space.

    Each entry describes one range as the system reports it: ``base`` and
    ``size`` are full width values, ``state`` is ``"commit"`` or ``"reserve"``,
    ``type`` is ``"image"``/``"mapped"``/``"private"``, ``protect`` is the short
    protection name, ``path`` is the openable path of the backing file or
    ``None``, and ``image`` says whether the range belongs to a loaded image.

    With ``include_reserved`` true both committed and reserved ranges are
    reported; with it false only committed ranges are.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        module_paths = _module_paths(handle, device_map)
        path_cache = {}
        result = []

        for base, size, state, protect, mem_type, alloc_base in _walk(handle, pid):
            if state == w.MEM_COMMIT:
                state_name = "commit"
            elif state == w.MEM_RESERVE:
                if not include_reserved:
                    continue
                state_name = "reserve"
            else:
                # free, or anything else that is not in use
                continue

            path = None
            if state == w.MEM_COMMIT and mem_type in (w.MEM_IMAGE, w.MEM_MAPPED):
                key = alloc_base or base
                if key in path_cache:
                    path = path_cache[key]
                else:
                    path = module_paths.get(key)
                    if path is None:
                        raw = _mapped_file_name(handle, base)
                        path = _dos_path(raw, device_map) if raw else None
                    path_cache[key] = path

            result.append({
                "base": base,
                "size": size,
                "state": state_name,
                "type": type_name(mem_type),
                "protect": protection_name(protect),
                "path": path,
                "image": mem_type == w.MEM_IMAGE,
            })

        result.sort(key=lambda item: item["base"])
        return result
    finally:
        w.CloseHandle(handle)


def file_backed_regions(pid):
    """Return only the regions that have a file behind them."""
    return [item for item in regions(pid) if item["path"] is not None]


def modules(pid):
    """Return the loaded executable images, lowest base address first.

    Every image appears exactly once and no file path is reported twice. An
    image whose file name cannot be expressed as an openable path is still
    listed, with ``path`` set to ``None``.
    """
    handle = _open_process(pid)
    try:
        device_map = _device_map()
        found = {}

        # The loader's own module list: authoritative bases, sizes and paths.
        if w.EnumProcessModulesEx is not None:
            for base, path in _module_paths(handle, device_map).items():
                size = _module_size(handle, w.HMODULE(base))
                found[base] = {"path": path, "base": base, "size": size}

        # Image regions, so that images the module list does not mention (or
        # cannot report, e.g. across a bitness boundary) are covered as well.
        spans = {}
        for base, size, state, _protect, mem_type, alloc_base in _walk(handle, pid):
            if mem_type != w.MEM_IMAGE:
                continue
            if state not in (w.MEM_COMMIT, w.MEM_RESERVE):
                continue
            key = alloc_base or base
            end = base + size
            previous = spans.get(key)
            if previous is None or end > previous:
                spans[key] = end

        for key, end in spans.items():
            entry = found.get(key)
            if entry is None:
                raw = _mapped_file_name(handle, key)
                found[key] = {
                    "path": _dos_path(raw, device_map) if raw else None,
                    "base": key,
                    "size": end - key,
                }
            elif not entry["size"]:
                entry["size"] = end - key

        # One entry per image file: the same file mapped twice is reported at
        # its lowest base address.
        by_path = {}
        unnamed = []
        for entry in found.values():
            if entry["size"] is None:
                entry["size"] = 0
            if entry["path"] is None:
                unnamed.append(entry)
                continue
            key = entry["path"].lower()
            previous = by_path.get(key)
            if previous is None or entry["base"] < previous["base"]:
                by_path[key] = entry

        result = list(by_path.values()) + unnamed
        result.sort(key=lambda item: item["base"])
        return result
    finally:
        w.CloseHandle(handle)

